import { getIsEquivalentTokens } from "../tokens";
export function getDecreaseReceiveOutputs({ decreaseAmounts, tokensData, }) {
    if (!decreaseAmounts || !tokensData) {
        return [];
    }
    return [
        { type: "primary", output: decreaseAmounts.primaryOutput },
        { type: "secondary", output: decreaseAmounts.secondaryOutput },
    ].reduce((acc, { type, output }) => {
        if (output.amount <= 0n) {
            return acc;
        }
        const token = tokensData[output.tokenAddress];
        if (!token) {
            return acc;
        }
        acc.push({
            type,
            token,
            amount: output.amount,
            usd: output.usd,
        });
        return acc;
    }, []);
}
export function getCanSplitReceive(position) {
    if (!position?.pnlToken || !position.collateralToken) {
        return false;
    }
    return !getIsEquivalentTokens(position.pnlToken, position.collateralToken);
}
export function getHasSplitReceiveOutputs(outputs) {
    if (outputs.length < 2) {
        return false;
    }
    return outputs.some((output) => !getIsEquivalentTokens(output.token, outputs[0].token));
}
export function getIsSplitReceiveAvailable(position, outputs) {
    return getCanSplitReceive(position) && getHasSplitReceiveOutputs(outputs);
}
